SINA_SMART["bacterio1-chlamydia"] = {"lecture":"bacterio1-chlamydia","title":"Chlamydia pneumoniae","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"bacterio1-chlamydia:e0","text":"Obligate intracellular, strictly human, droplet spread, no animal reservoir.","topic":"General characteristics","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-chlamydia:e1","text":"Third cause of community pneumonia (lecture); often asymptomatic.","topic":"General characteristics","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-chlamydia:e2","text":"No classical peptidoglycan; energy parasite; hard to culture.","topic":"General characteristics","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-chlamydia:e3","text":"EB: infectious, inert; RB: replicative, non-infectious.","topic":"General characteristics","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-chlamydia:e4","text":"Targets non-ciliated epithelium and macrophages; blocks phagolysosome fusion.","topic":"Virulence and pathogenesis","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-chlamydia:e5","text":"MOMP, Inc proteins, type III secretion; aberrant bodies = persistence.","topic":"Virulence and pathogenesis","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-chlamydia:e6","text":"Pharyngitis, sinusitis, bronchitis, atypical pneumonia; asthma, COPD, atherosclerosis links.","topic":"Clinical picture","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-chlamydia:e7","text":"Diagnosis: PCR (ompA, 16S, incA); MIF serology slow (IgM 3 wk, IgG 6-8 wk).","topic":"Diagnosis","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-chlamydia:e8","text":"Macrolides first line; doxycycline or fluoroquinolone; ≥ 10-14 days.","topic":"Treatment and prevention","sec":4,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-chlamydia:e9","text":"β-lactams useless; no vaccine.","topic":"Treatment and prevention","sec":4,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"1nn52vo":"a","qricph":"a","1tn0clu":"a","1bgbj0b":"a","eewtv1":"a","rkk1r6":"a","122s1vp":"a","uxp7hs":"a","b4hwvr":"a","ckbo7i":"a","ta355p":"a","1cequy3":"a","5qedlc":"a","1pmk4z4":"a","1an6w55":"a"},"mapCounts":{"verified":0,"auto":15,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"bacterio1-chlamydia:e0":{"s":0,"u":["Obligate intracellular, strictly human, droplet spread, no animal reservoir.","Chlamydia pneumoniae is an obligate intracellular bacterium, a strict human respiratory pathogen with no animal reservoir , spread by droplets."],"dp":[]},"bacterio1-chlamydia:e1":{"s":0,"u":["Third cause of community pneumonia (lecture); often asymptomatic.","The lecture ranks it the third cause of community-acquired pneumonia after S. pneumoniae and H. influenzae .","Infection is often asymptomatic or mild and can persist; it is associated with chronic respiratory disease and, controversially, atherosclerosis ."],"dp":[{"h":"Why 'atypical' pneumonias ignore amoxicillin","t":"Amoxicillin, the standard first choice for community pneumonia, targets penicillin-binding proteins that build peptidoglycan. Chlamydia lacks a classical peptidoglycan wall and hides inside cells; Mycoplasma has no wall at all; Legionella lives inside macrophages. These 'atypical' organisms therefore need drugs that reach inside cells and act on ribosomes or DNA: macrolides, tetracyclines or fluoroquinolones. That is why a young adult with a dry cough and a pneumonia that does not improve on amoxicillin is often switched to a macrolide. Source: the lecture's treatment notes and the Mycoplasma lecture."}]},"bacterio1-chlamydia:e2":{"s":0,"u":["No classical peptidoglycan; energy parasite; hard to culture.","It has a Gram-negative-like envelope but lacks classical peptidoglycan , is non-motile, and depends on the host for ATP ('energy parasite'): it grows only inside cells, in membrane-bound inclusions, so it is extremely difficult to culture."],"dp":[]},"bacterio1-chlamydia:e3":{"s":0,"u":["EB: infectious, inert; RB: replicative, non-infectious.","Its biphasic cycle : the elementary body (EB, 0.2-0.3 µm) is infectious and metabolically inactive; the reticulate body (RB, 0.8-1 µm) is non-infectious and replicates."],"dp":[]},"bacterio1-chlamydia:e4":{"s":1,"u":["Targets non-ciliated epithelium and macrophages; blocks phagolysosome fusion.","Targets: non-ciliated respiratory epithelial cells and macrophages (which carry it to other sites, including the vascular endothelium)."],"dp":[]},"bacterio1-chlamydia:e5":{"s":1,"u":["MOMP, Inc proteins, type III secretion; aberrant bodies = persistence.","Virulence factors: MOMP and other outer membrane proteins (attachment and entry), inclusion membrane proteins (Incs) maintaining the protected vacuole, secreted proteins via a type III secretion system that modulate host signalling, apoptosis and immunity, inhibition of phagolysosome fusion , LPS (weak endotoxin but immunogenic) and proteases.","Stress (e.g. interferon-γ) produces aberrant bodies : persistent infection and chronic inflammation."],"dp":[]},"bacterio1-chlamydia:e6":{"s":2,"u":["Pharyngitis, sinusitis, bronchitis, atypical pneumonia; asthma, COPD, atherosclerosis links.","Symptomatic disease: pharyngitis, sinusitis, bronchitis and atypical pneumonia (gradual onset, dry cough, few signs).","Chronic associations: asthma exacerbations , COPD ; systemic association with atherosclerotic cardiovascular disease ."],"dp":[]},"bacterio1-chlamydia:e7":{"s":3,"u":["Diagnosis: PCR (ompA, 16S, incA); MIF serology slow (IgM 3 wk, IgG 6-8 wk).","Direct : NAATs (PCR) targeting ompA, 16S rRNA or incA, the method of choice; direct fluorescent antibody staining of infected HEp-2 cells is rarely used."],"dp":[]},"bacterio1-chlamydia:e8":{"s":4,"u":["Macrolides first line; doxycycline or fluoroquinolone; ≥ 10-14 days.","First line: macrolides (azithromycin, clarithromycin).","Alternatives: doxycycline or a respiratory fluoroquinolone (levofloxacin, moxifloxacin) in severe cases."],"dp":[]},"bacterio1-chlamydia:e9":{"s":4,"u":["β-lactams useless; no vaccine."],"dp":[]}},"meta":{"1nn52vo":{"a":"recall","vg":"bacterio1-chlamydia:e0/recall/1"},"qricph":{"a":"recall","vg":"bacterio1-chlamydia:e3/recall/1"},"1tn0clu":{"a":"recall","vg":"bacterio1-chlamydia:e3/recall/1"},"1bgbj0b":{"a":"recall","vg":"bacterio1-chlamydia:e2/recall/1"},"eewtv1":{"a":"recall","vg":"bacterio1-chlamydia:e2/recall/2"},"rkk1r6":{"a":"recall","vg":"bacterio1-chlamydia:e0/recall/2"},"122s1vp":{"a":"recall","vg":"bacterio1-chlamydia:e7/recall/1"},"uxp7hs":{"a":"recall","vg":"bacterio1-chlamydia:e7/recall/2"},"b4hwvr":{"a":"recall","vg":"bacterio1-chlamydia:e8/recall/1"},"ckbo7i":{"a":"recall","vg":"bacterio1-chlamydia:e1/recall/1"},"ta355p":{"a":"recall","vg":"bacterio1-chlamydia:e1/recall/2"},"1cequy3":{"a":"recall","vg":"bacterio1-chlamydia:e4/recall/1"},"5qedlc":{"a":"recall","vg":"bacterio1-chlamydia:e5/recall/1"},"1pmk4z4":{"a":"relationship","vg":"bacterio1-chlamydia:e1/relationship/1"},"1an6w55":{"a":"recall","vg":"bacterio1-chlamydia:e9/recall/1"}},"explRev":"3148a1ef9b32"};
